:root {
  --ink: #050a12;
  --ink-soft: #0b1422;
  --snow: #eef5f6;
  --snow-dim: #b9c9cd;
  --frost: #9edbe8;
  --frost-bright: #cef7ff;
  --gold: #e7bd77;
  --gold-bright: #ffdfa2;
  --gold-deep: #9a6b33;
  --health: #d65f67;
  --magicka: #75b8f4;
  --stamina: #77cca3;
  --blood: #b4464f;
  --glass: rgba(9, 18, 29, 0.62);
  --glass-heavy: rgba(6, 13, 23, 0.88);
  --stroke: rgba(210, 238, 245, 0.15);
  --serif: "Cinzel", "Times New Roman", serif;
  --sans: "Manrope", "Helvetica Neue", system-ui, sans-serif;
  --safe-top: max(14px, env(safe-area-inset-top));
  --safe-bottom: max(14px, env(safe-area-inset-bottom));
  --safe-left: max(16px, env(safe-area-inset-left));
  --safe-right: max(16px, env(safe-area-inset-right));
}

* {
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

html,
body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  overscroll-behavior: none;
  background: var(--ink);
  color: var(--snow);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  user-select: none;
  -webkit-user-select: none;
}

body {
  position: fixed;
  inset: 0;
  touch-action: none;
}

button,
input {
  font: inherit;
  color: inherit;
}

button {
  border: 0;
  background: none;
  padding: 0;
  cursor: pointer;
  touch-action: manipulation;
}

button:focus-visible,
input:focus-visible {
  outline: 1px solid var(--gold-bright);
  outline-offset: 4px;
}

.hidden {
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
}

.svg-defs {
  position: fixed;
  width: 0;
  height: 0;
  overflow: hidden;
}

svg {
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
}

#app {
  position: relative;
  width: 100%;
  height: 100%;
  height: 100dvh;
  overflow: hidden;
  isolation: isolate;
  background:
    radial-gradient(ellipse at 55% 35%, #122636 0%, #07101b 55%, #03070d 100%);
}

#game-canvas {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  outline: none;
}

.world-grade {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 42%, transparent 38%, rgba(2, 7, 14, 0.32) 100%),
    linear-gradient(180deg, rgba(5, 12, 23, 0.1), transparent 28%, transparent 73%, rgba(2, 6, 12, 0.48));
}

.grain {
  position: absolute;
  inset: -20%;
  z-index: 3;
  pointer-events: none;
  opacity: 0.075;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 220 220' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.92' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.65'/%3E%3C/svg%3E");
  background-size: 180px 180px;
  mix-blend-mode: soft-light;
  animation: grain-shift 0.8s steps(2) infinite;
}

@keyframes grain-shift {
  0% { transform: translate3d(0, 0, 0); }
  25% { transform: translate3d(-2%, 1.5%, 0); }
  50% { transform: translate3d(1.5%, -1%, 0); }
  75% { transform: translate3d(-1%, -2%, 0); }
  100% { transform: translate3d(2%, 1%, 0); }
}

#damage-vignette {
  position: absolute;
  inset: 0;
  z-index: 12;
  pointer-events: none;
  opacity: 0;
  background:
    radial-gradient(ellipse at center, transparent 42%, rgba(128, 13, 24, 0.72) 118%),
    linear-gradient(180deg, rgba(108, 12, 22, 0.22), transparent 30%);
  mix-blend-mode: multiply;
  transition: opacity 0.38s ease;
}
#damage-vignette.hit { opacity: 1; transition-duration: 0.06s; }

#frost-vignette {
  position: absolute;
  inset: 0;
  z-index: 11;
  pointer-events: none;
  opacity: 0.5;
  background:
    radial-gradient(ellipse at center, transparent 54%, rgba(167, 222, 235, 0.11) 100%),
    linear-gradient(115deg, rgba(190, 234, 244, 0.06), transparent 18%, transparent 82%, rgba(190, 234, 244, 0.07));
  mix-blend-mode: screen;
}

#screen-fader {
  position: absolute;
  inset: 0;
  z-index: 80;
  pointer-events: none;
  background: #02060c;
  opacity: 0;
  transition: opacity 1s ease;
}
#screen-fader.visible { opacity: 1; }

/* ========================================================================== */
/* TITLE SCREEN                                                               */
/* ========================================================================== */

.title-screen {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: flex;
  flex-direction: column;
  padding: var(--safe-top) var(--safe-right) var(--safe-bottom) var(--safe-left);
  transition: opacity 0.8s ease, visibility 0.8s;
}

.title-scrim {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background:
    linear-gradient(90deg, rgba(2, 6, 12, 0.86) 0%, rgba(3, 8, 15, 0.68) 31%, rgba(3, 8, 15, 0.16) 65%, transparent 100%),
    linear-gradient(180deg, rgba(2, 6, 12, 0.45), transparent 24%, transparent 63%, rgba(2, 6, 12, 0.82) 100%);
}

.title-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 18px;
  flex: none;
  position: relative;
  z-index: 2;
  animation: fade-down 1s 0.1s both cubic-bezier(0.2, 0.8, 0.2, 1);
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--snow);
  text-decoration: none;
}

.brand-mark {
  width: 43px;
  height: 43px;
  display: grid;
  place-items: center;
  color: var(--gold-bright);
  border: 1px solid rgba(231, 189, 119, 0.52);
  transform: rotate(45deg);
  background: linear-gradient(135deg, rgba(231, 189, 119, 0.18), rgba(8, 17, 28, 0.55));
  box-shadow: inset 0 0 18px rgba(231, 189, 119, 0.08), 0 0 28px rgba(231, 189, 119, 0.08);
}
.brand-mark svg { width: 22px; height: 22px; transform: rotate(-45deg); }
.brand-copy { display: flex; flex-direction: column; line-height: 1; }
.brand-copy strong {
  font-family: var(--serif);
  font-size: 15px;
  letter-spacing: 0.28em;
  font-weight: 700;
}
.brand-copy small {
  margin-top: 6px;
  color: var(--snow-dim);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.34em;
  text-transform: uppercase;
}

.title-tools { display: flex; align-items: center; gap: 9px; }

.icon-button {
  width: 42px;
  height: 42px;
  display: inline-grid;
  place-items: center;
  border-radius: 50%;
  color: var(--snow);
  border: 1px solid var(--stroke);
  background: rgba(7, 15, 26, 0.46);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  transition: border-color 0.2s, background 0.2s, transform 0.15s;
}
.icon-button:hover { background: rgba(18, 35, 48, 0.7); border-color: rgba(231, 189, 119, 0.45); }
.icon-button:active { transform: scale(0.94); }
.icon-button svg { width: 19px; height: 19px; }
.icon-button .when-off { display: none; }
.icon-button.muted .when-on { display: none; }
.icon-button.muted .when-off { display: block; }

.pill-button {
  height: 42px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 15px;
  border-radius: 99px;
  border: 1px solid var(--stroke);
  background: rgba(7, 15, 26, 0.46);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--snow-dim);
  transition: all 0.2s;
}
.pill-button svg { width: 17px; height: 17px; }
.pill-button:hover { color: var(--snow); border-color: rgba(231, 189, 119, 0.42); }
.pill-button .status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.18);
  transition: background 0.2s, box-shadow 0.2s;
}
.pill-button.active {
  color: var(--gold-bright);
  border-color: rgba(231, 189, 119, 0.48);
  background: rgba(83, 58, 24, 0.23);
}
.pill-button.active .status-dot {
  background: var(--gold-bright);
  box-shadow: 0 0 9px var(--gold);
}

.title-hero {
  margin: auto 0;
  padding-left: clamp(0px, 6.5vw, 110px);
  max-width: min(760px, 78vw);
  position: relative;
  z-index: 2;
  transform: translateY(-2vh);
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 14px;
  color: var(--gold);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.34em;
  text-transform: uppercase;
  animation: fade-up 1s 0.25s both cubic-bezier(0.2, 0.8, 0.2, 1);
}
.eyebrow-line { width: clamp(24px, 4vw, 55px); height: 1px; background: linear-gradient(90deg, transparent, var(--gold)); }
.eyebrow-line:last-child { background: linear-gradient(90deg, var(--gold), transparent); }

.game-logo {
  margin: 12px 0 0 -0.055em;
  font-family: var(--serif);
  font-size: clamp(74px, 11.5vw, 176px);
  line-height: 0.85;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: #eaf6fa;
  text-shadow: 0 4px 45px rgba(118, 198, 218, 0.18), 0 2px 2px rgba(0, 0, 0, 0.5);
  animation: logo-in 1.3s 0.2s both cubic-bezier(0.16, 0.84, 0.24, 1);
}
.game-logo span {
  background: linear-gradient(160deg, #fff1cf 0%, #e7bd77 42%, #b67c38 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 26px rgba(230, 181, 98, 0.17));
}
@keyframes logo-in {
  from { opacity: 0; transform: translateY(24px) scale(0.985); filter: blur(6px); }
  to { opacity: 1; transform: none; filter: blur(0); }
}

.game-subtitle {
  margin: 15px 0 0;
  font-family: var(--serif);
  font-size: clamp(12px, 1.35vw, 17px);
  letter-spacing: 0.65em;
  font-weight: 600;
  color: var(--gold);
  text-transform: uppercase;
  animation: fade-up 1s 0.55s both cubic-bezier(0.2, 0.8, 0.2, 1);
}
.game-pitch {
  margin: 25px 0 0;
  max-width: 430px;
  color: #c2d2d7;
  font-size: clamp(13px, 1.12vw, 15px);
  line-height: 1.72;
  font-weight: 500;
  text-shadow: 0 1px 8px rgba(0, 0, 0, 0.8);
  animation: fade-up 1s 0.68s both cubic-bezier(0.2, 0.8, 0.2, 1);
}

.title-cta {
  margin-top: 31px;
  display: flex;
  align-items: center;
  gap: 12px;
  animation: fade-up 1s 0.82s both cubic-bezier(0.2, 0.8, 0.2, 1);
}

.primary-button {
  position: relative;
  overflow: hidden;
  min-height: 53px;
  padding: 0 24px;
  border-radius: 3px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 13px;
  color: #1d140a;
  background: linear-gradient(125deg, #f3d7a1 0%, #e6b96f 45%, #c28a45 100%);
  border: 1px solid rgba(255, 236, 196, 0.72);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.55);
  transition: transform 0.16s, filter 0.2s, box-shadow 0.2s;
}
.primary-button:hover { filter: brightness(1.07); box-shadow: 0 10px 38px rgba(196, 139, 63, 0.24), inset 0 1px 0 rgba(255, 255, 255, 0.55); }
.primary-button:active { transform: scale(0.975); }
.primary-button svg { width: 15px; height: 15px; fill: currentColor; stroke: none; margin-left: 2px; }
.primary-button span { position: relative; z-index: 1; }
.button-shine {
  position: absolute;
  top: -30%;
  bottom: -30%;
  width: 32%;
  left: -45%;
  transform: skewX(-20deg);
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.52), transparent);
  animation: button-glint 5.5s 2s infinite;
}
@keyframes button-glint {
  0%, 66% { left: -45%; }
  82%, 100% { left: 125%; }
}

.secondary-button {
  min-height: 53px;
  padding: 0 26px;
  border: 1px solid rgba(216, 237, 241, 0.2);
  border-radius: 3px;
  background: rgba(7, 15, 26, 0.36);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--snow);
  transition: all 0.2s;
}
.secondary-button:hover:not(:disabled) { border-color: rgba(231, 189, 119, 0.45); background: rgba(16, 31, 44, 0.56); }
.secondary-button:disabled { opacity: 0.28; cursor: not-allowed; }

.title-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 22px;
  margin-top: 27px;
  color: rgba(198, 218, 223, 0.62);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.19em;
  text-transform: uppercase;
  animation: fade-up 1s 1s both cubic-bezier(0.2, 0.8, 0.2, 1);
}
.title-meta span { display: flex; align-items: center; gap: 7px; }
.title-meta svg { width: 13px; height: 13px; color: var(--gold); opacity: 0.8; }

.title-footer {
  flex: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding-bottom: 3px;
  color: rgba(193, 216, 221, 0.55);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  position: relative;
  z-index: 2;
  animation: fade-up 1s 1.15s both;
}
.title-note { display: flex; align-items: center; gap: 9px; }
.live-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--gold);
  box-shadow: 0 0 8px var(--gold);
  animation: soft-pulse 2.4s infinite;
}
.title-hint { text-align: right; }
.title-hint b { color: var(--gold); font-weight: 800; }
.title-hint.flash { animation: hint-flash 0.8s 2; }

@keyframes fade-up { from { opacity: 0; transform: translateY(15px); } to { opacity: 1; transform: none; } }
@keyframes fade-down { from { opacity: 0; transform: translateY(-12px); } to { opacity: 1; transform: none; } }
@keyframes soft-pulse { 0%, 100% { opacity: 0.55; } 50% { opacity: 1; } }
@keyframes hint-flash { 50% { color: var(--gold-bright); text-shadow: 0 0 15px rgba(231, 189, 119, 0.6); } }

/* ========================================================================== */
/* CREATOR / MODALS                                                           */
/* ========================================================================== */

.modal-layer {
  position: absolute;
  inset: 0;
  z-index: 50;
  display: grid;
  place-items: center;
  padding: max(18px, env(safe-area-inset-top)) max(18px, env(safe-area-inset-right)) max(18px, env(safe-area-inset-bottom)) max(18px, env(safe-area-inset-left));
  transition: opacity 0.3s, visibility 0.3s;
}

.modal-backdrop {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 55% 40%, rgba(8, 21, 34, 0.58), rgba(2, 6, 11, 0.9));
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}

.creator-panel,
.pause-panel {
  position: relative;
  z-index: 1;
  width: min(960px, 100%);
  max-height: min(92dvh, 760px);
  overflow: auto;
  scrollbar-width: thin;
  scrollbar-color: rgba(231, 189, 119, 0.3) transparent;
  border: 1px solid rgba(210, 239, 245, 0.16);
  background:
    linear-gradient(135deg, rgba(17, 35, 49, 0.72), rgba(6, 13, 23, 0.94) 52%, rgba(10, 20, 31, 0.9));
  box-shadow: 0 28px 90px rgba(0, 0, 0, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(25px) saturate(1.15);
  -webkit-backdrop-filter: blur(25px) saturate(1.15);
  animation: modal-in 0.45s cubic-bezier(0.2, 0.85, 0.2, 1) both;
}
.creator-panel { padding: clamp(26px, 4vw, 50px); }
.creator-panel::before,
.pause-panel::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(90deg, transparent, rgba(231, 189, 119, 0.16), transparent) top / 100% 1px no-repeat,
    radial-gradient(ellipse at 10% 0%, rgba(231, 189, 119, 0.09), transparent 45%);
}
@keyframes modal-in { from { opacity: 0; transform: translateY(16px) scale(0.985); } to { opacity: 1; transform: none; } }

.modal-close {
  position: absolute;
  top: 17px;
  right: 17px;
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border: 1px solid var(--stroke);
  border-radius: 50%;
  color: var(--snow-dim);
  z-index: 2;
  transition: all 0.2s;
}
.modal-close:hover { color: var(--snow); border-color: rgba(231, 189, 119, 0.5); transform: rotate(90deg); }
.modal-close svg { width: 16px; height: 16px; }

.creator-heading { margin-bottom: 27px; }
.kicker {
  display: block;
  color: var(--gold);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.32em;
  text-transform: uppercase;
}
.creator-heading h2,
.pause-panel h2 {
  margin: 8px 0 7px;
  font-family: var(--serif);
  font-weight: 700;
  font-size: clamp(27px, 3.2vw, 42px);
  letter-spacing: 0.01em;
  line-height: 1.08;
}
.creator-heading p,
.pause-panel > p {
  margin: 0;
  max-width: 560px;
  color: var(--snow-dim);
  font-size: 12px;
  line-height: 1.6;
}

.creator-grid {
  display: grid;
  grid-template-columns: minmax(205px, 0.76fr) minmax(320px, 1.24fr);
  gap: clamp(24px, 4vw, 54px);
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  padding-top: 27px;
}

.field-label {
  display: block;
  margin-bottom: 8px;
  color: rgba(207, 226, 231, 0.56);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.25em;
  text-transform: uppercase;
}
.fur-label { margin-top: 24px; }

.name-input {
  width: 100%;
  height: 47px;
  padding: 0 14px;
  border: 1px solid rgba(215, 238, 243, 0.16);
  border-radius: 2px;
  background: rgba(3, 9, 17, 0.42);
