  -webkit-user-select: text;
}
.name-input:focus { border-color: rgba(231, 189, 119, 0.58); background: rgba(8, 17, 28, 0.65); outline: none; }

.fur-row { display: flex; flex-wrap: wrap; gap: 12px; }
.fur-swatch {
  position: relative;
  width: 41px;
  height: 41px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.14);
  background:
    radial-gradient(circle at 33% 27%, rgba(255, 255, 255, 0.5), transparent 27%),
