.creator-preview {
  display: flex;
  align-items: center;
  gap: 13px;
  margin-top: 26px;
  padding-top: 21px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}
.cat-portrait {
  position: relative;
  flex: none;
  width: 62px;
  height: 62px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  overflow: hidden;
  background: radial-gradient(circle at 40% 35%, rgba(176, 224, 234, 0.2), rgba(3, 10, 18, 0.85));
  border: 1px solid rgba(210, 238, 245, 0.18);
}
.cat-portrait::before {
  content: "";
  position: absolute;
