}
.cat-portrait svg { width: 82%; height: 82%; filter: drop-shadow(0 3px 4px rgba(0, 0, 0, 0.35)); }
.creator-preview strong { display: block; font-family: var(--serif); font-size: 17px; letter-spacing: 0.04em; }
.creator-preview span { display: block; margin-top: 4px; color: rgba(196, 219, 224, 0.55); font-size: 9px; font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; }

.path-list { display: flex; flex-direction: column; gap: 9px; }
.path-card {
  position: relative;
  width: 100%;
  display: flex;
  align-items: center;
  gap: 14px;
  min-height: 73px;
  padding: 12px 14px;
