}
.path-icon {
  width: 43px;
  height: 43px;
  flex: none;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: var(--gold);
  background: rgba(231, 189, 119, 0.08);
  border: 1px solid rgba(231, 189, 119, 0.17);
}
.path-icon svg { width: 21px; height: 21px; }
.path-copy { min-width: 0; display: flex; flex-direction: column; gap: 4px; }
.path-copy strong { font-family: var(--serif); font-size: 15px; letter-spacing: 0.04em; }
.path-copy small { color: rgba(195, 218, 223, 0.6); font-size: 10px; line-height: 1.35; }
.path-bonus {
  margin-left: auto;
  color: rgba(231, 189, 119, 0.8);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.15em;
  white-space: nowrap;
}

.creator-footer {
  margin-top: 28px;
  padding-top: 22px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}
.creator-tip { color: rgba(195, 218, 223, 0.45); font-size: 9px; letter-spacing: 0.05em; }
.enter-button { min-width: 230px; }

/* ========================================================================== */
/* HUD                                                                        */
/* ========================================================================== */

.hud {
  position: absolute;
  inset: 0;
  z-index: 15;
  pointer-events: none;
  transition: opacity 0.55s ease, visibility 0.55s;
}
.hud button { pointer-events: auto; }

.status-card {
  position: absolute;
  top: var(--safe-top);
  left: var(--safe-left);
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 8px 13px 8px 8px;
  width: 241px;
  border: 1px solid rgba(211, 239, 245, 0.13);
  border-left: 2px solid rgba(231, 189, 119, 0.48);
  background: linear-gradient(90deg, rgba(5, 12, 21, 0.8), rgba(6, 14, 24, 0.47));
  box-shadow: 0 8px 26px rgba(0, 0, 0, 0.22);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}
.hud-portrait { width: 49px; height: 49px; }
.hud-portrait svg { width: 84%; height: 84%; }
.status-main { flex: 1; min-width: 0; }
.status-name-row { display: flex; align-items: baseline; justify-content: space-between; margin: 0 0 6px; }
.status-name-row strong { font-family: var(--serif); font-size: 13px; letter-spacing: 0.07em; font-weight: 600; }
.status-name-row span { color: rgba(202, 224, 229, 0.48); font-size: 7px; font-weight: 800; letter-spacing: 0.15em; text-transform: uppercase; }
.stat-bar {
  position: relative;
  height: 6px;
  margin-top: 3px;
  border-radius: 1px;
  background: rgba(0, 0, 0, 0.46);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.06);
  overflow: visible;
}
.stat-bar i {
  position: absolute;
  inset: 0;
  display: block;
  border-radius: 1px;
  transform-origin: left center;
  transition: width 0.28s ease;
}
.stat-bar.health i { width: 100%; background: linear-gradient(90deg, #9a3743, var(--health)); box-shadow: 0 0 7px rgba(214, 95, 103, 0.24); }
.stat-bar.magicka i { width: 100%; background: linear-gradient(90deg, #356b9c, var(--magicka)); box-shadow: 0 0 7px rgba(117, 184, 244, 0.24); }
.stat-bar.stamina i { width: 100%; background: linear-gradient(90deg, #3b7b61, var(--stamina)); box-shadow: 0 0 7px rgba(119, 204, 163, 0.22); }
.stat-bar span {
  position: absolute;
  right: 0;
  top: -11px;
  color: rgba(221, 238, 241, 0.5);
  font-size: 6px;
  font-weight: 800;
  letter-spacing: 0.06em;
  display: none;
}

.compass-wrap {
  position: absolute;
  top: var(--safe-top);
  left: 50%;
  width: min(390px, 39vw);
  height: 49px;
  transform: translateX(-50%);
  overflow: hidden;
  mask-image: linear-gradient(90deg, transparent, #000 14%, #000 86%, transparent);
  -webkit-mask-image: linear-gradient(90deg, transparent, #000 14%, #000 86%, transparent);
}
.compass-wrap::before,
.compass-wrap::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(216, 239, 245, 0.14), transparent);
}
.compass-wrap::before { top: 32px; }
.compass-wrap::after { bottom: 3px; opacity: 0.4; }
.compass-track { position: absolute; inset: 0; }
.compass-label {
  position: absolute;
  top: 5px;
  color: rgba(211, 231, 236, 0.42);
  font-family: var(--serif);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.13em;
  transform: translateX(-50%);
  transition: color 0.15s;
}
.compass-label.cardinal { top: 3px; color: rgba(231, 242, 245, 0.8); font-size: 11px; }
.compass-label.minor { top: 8px; font-size: 6px; opacity: 0.55; }
.compass-label.cardinal::after {
  content: "";
  display: block;
  width: 1px;
  height: 5px;
  margin: 3px auto 0;
  background: currentColor;
  opacity: 0.32;
}
.compass-needle {
  position: absolute;
  left: 50%;
  top: 1px;
  width: 1px;
  height: 34px;
  background: linear-gradient(180deg, var(--gold-bright), rgba(231, 189, 119, 0.12));
  box-shadow: 0 0 7px rgba(231, 189, 119, 0.5);
}
.compass-needle::before {
  content: "";
  position: absolute;
  top: 0;
  left: -3px;
  border-left: 3px solid transparent;
  border-right: 3px solid transparent;
  border-top: 4px solid var(--gold-bright);
}
.quest-marker {
