  box-shadow: 0 0 10px rgba(231, 189, 119, 0.55), inset 0 0 5px rgba(231, 189, 119, 0.3);
}
.quest-marker.offscreen { opacity: 0.3; }

.hud-top-right {
  position: absolute;
  top: var(--safe-top);
  right: var(--safe-right);
  display: flex;
  align-items: center;
  gap: 9px;
}
.time-chip {
  height: 36px;
