  background: rgba(5, 12, 22, 0.42);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  color: rgba(203, 226, 231, 0.62);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}
.moon-glyph { color: var(--gold); font-size: 14px; line-height: 1; transform: translateY(-1px); }
.hud-icon { width: 36px; height: 36px; }
.hud-icon svg { width: 16px; height: 16px; }

.quest-card {
  position: absolute;
  top: calc(var(--safe-top) + 65px);
  left: var(--safe-left);
  width: 263px;
  padding: 12px 15px 11px;
  border-left: 1px solid rgba(231, 189, 119, 0.43);
  background: linear-gradient(90deg, rgba(6, 14, 24, 0.62), rgba(6, 14, 24, 0.08));
