  height: 17px;
  background: var(--gold-bright);
  box-shadow: 0 0 8px var(--gold);
}
.quest-kicker { display: block; color: var(--gold); font-size: 7px; font-weight: 800; letter-spacing: 0.24em; text-transform: uppercase; margin-bottom: 5px; }
.quest-card > strong { display: block; font-family: var(--serif); font-size: 14px; letter-spacing: 0.03em; font-weight: 600; line-height: 1.3; }
.quest-objective { display: flex; align-items: center; gap: 7px; margin-top: 8px; color: rgba(195, 218, 223, 0.64); font-size: 8px; font-weight: 600; letter-spacing: 0.03em; }
.quest-diamond { width: 5px; height: 5px; flex: none; border: 1px solid rgba(231, 189, 119, 0.8); transform: rotate(45deg); }
.quest-objective b { margin-left: auto; color: rgba(231, 189, 119, 0.72); font-size: 7px; letter-spacing: 0.1em; white-space: nowrap; }

.boss-wrap {
