  flex-direction: column;
  align-items: center;
  gap: 7px;
  z-index: 2;
}
.toast {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 17px;
  border: 1px solid rgba(231, 189, 119, 0.25);
  background: linear-gradient(90deg, rgba(29, 23, 14, 0.62), rgba(4, 11, 20, 0.72), rgba(29, 23, 14, 0.62));
