  border-radius: 50%;
}
.joystick-ring {
  position: absolute;
  inset: 12px;
  border-radius: 50%;
  border: 1px solid rgba(214, 241, 247, 0.16);
  background:
    radial-gradient(circle at center, rgba(12, 26, 39, 0.38), rgba(4, 11, 20, 0.17) 70%),
    conic-gradient(from 45deg, transparent 0 22%, rgba(231, 189, 119, 0.07) 22% 25%, transparent 25% 47%, rgba(231, 189, 119, 0.07) 47% 50%, transparent 50% 72%, rgba(231, 189, 119, 0.07) 72% 75%, transparent 75%);
  box-shadow: inset 0 0 24px rgba(0, 0, 0, 0.25), 0 0 0 7px rgba(5, 13, 22, 0.12);
  backdrop-filter: blur(5px);
  -webkit-backdrop-filter: blur(5px);
}
.joystick-ring::before {
  content: "";
  position: absolute;
  inset: 18px;
  border-radius: 50%;
  border: 1px solid rgba(214, 241, 247, 0.06);
}
.joystick-arrows { position: absolute; inset: 17px; color: rgba(218, 239, 243, 0.2); font-size: 6px; }
.joystick-arrows span { position: absolute; }
.joystick-arrows span:nth-child(1) { top: 2px; left: 50%; transform: translateX(-50%); }
.joystick-arrows span:nth-child(2) { bottom: 2px; left: 50%; transform: translateX(-50%); }
.joystick-arrows span:nth-child(3) { left: 2px; top: 50%; transform: translateY(-50%); }
.joystick-arrows span:nth-child(4) { right: 2px; top: 50%; transform: translateY(-50%); }
.joystick-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 58px;
  height: 58px;
  margin: -29px 0 0 -29px;
  border-radius: 50%;
  border: 1px solid rgba(231, 189, 119, 0.38);
  background:
    radial-gradient(circle at 38% 30%, rgba(255, 245, 216, 0.28), transparent 26%),
    radial-gradient(circle at center, rgba(31, 46, 56, 0.92), rgba(8, 17, 27, 0.96));
  box-shadow: 0 5px 18px rgba(0, 0, 0, 0.4), inset 0 0 16px rgba(231, 189, 119, 0.06);
  transition: box-shadow 0.2s;
  will-change: transform;
}
.joystick-knob span {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 7px;
  height: 7px;
  margin: -3.5px 0 0 -3.5px;
  border: 1px solid rgba(231, 189, 119, 0.68);
  transform: rotate(45deg);
}
.joystick-zone.active .joystick-knob { box-shadow: 0 5px 20px rgba(0, 0, 0, 0.4), 0 0 18px rgba(231, 189, 119, 0.12), inset 0 0 16px rgba(231, 189, 119, 0.12); }

.action-cluster {
  position: absolute;
  right: calc(var(--safe-right) - 3px);
  bottom: calc(var(--safe-bottom) - 1px);
  width: 216px;
  height: 196px;
  pointer-events: none;
}
.action-button {
  position: absolute;
  pointer-events: auto;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: rgba(233, 245, 247, 0.9);
  border: 1px solid rgba(216, 241, 246, 0.2);
  background:
    radial-gradient(circle at 38% 28%, rgba(255, 255, 255, 0.12), transparent 33%),
    linear-gradient(145deg, rgba(20, 41, 53, 0.74), rgba(4, 12, 21, 0.86));
  box-shadow: 0 7px 20px rgba(0, 0, 0, 0.32), inset 0 0 0 5px rgba(0, 0, 0, 0.08);
  backdrop-filter: blur(9px);
  -webkit-backdrop-filter: blur(9px);
  touch-action: none;
  transition: transform 0.11s, filter 0.15s, border-color 0.18s;
  overflow: hidden;
}
.action-button svg { width: 27%; height: 27%; pointer-events: none; filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.75)); }
.action-button .label {
  position: absolute;
  left: 50%;
  bottom: 13px;
  transform: translateX(-50%);
  font-size: 6px;
  font-weight: 800;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: rgba(219, 238, 242, 0.52);
  pointer-events: none;
  white-space: nowrap;
}
.action-button .key { display: none; }
.action-button:active { transform: scale(0.92); filter: brightness(1.16); }
.action-button.cooling { border-color: rgba(217, 236, 240, 0.09); color: rgba(219, 238, 242, 0.38); }
.action-button.pulse { animation: action-pulse 0.32s ease; }
@keyframes action-pulse { 50% { box-shadow: 0 0 0 12px rgba(231, 189, 119, 0), 0 0 28px rgba(231, 189, 119, 0.2); } }
.action-button .cooldown {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: conic-gradient(rgba(1, 5, 10, 0.62) calc(var(--cd, 0) * 1turn), transparent 0);
  pointer-events: none;
  opacity: 0;
}
.action-button.cooling .cooldown { opacity: 1; }

.action-button.attack {
  width: 87px;
  height: 87px;
  right: 8px;
  bottom: 7px;
  border-color: rgba(231, 189, 119, 0.42);
  background:
    radial-gradient(circle at 38% 28%, rgba(255, 244, 213, 0.2), transparent 33%),
    linear-gradient(145deg, rgba(87, 61, 31, 0.76), rgba(24, 19, 15, 0.93));
  box-shadow: 0 7px 24px rgba(0, 0, 0, 0.38), 0 0 25px rgba(231, 189, 119, 0.07), inset 0 0 22px rgba(231, 189, 119, 0.06);
  color: #f8e6c4;
}
.action-button.attack svg { width: 35%; height: 35%; }
.action-button.attack .label { bottom: 16px; color: rgba(248, 230, 196, 0.74); font-size: 7px; }
.action-button.spell {
  width: 67px;
  height: 67px;
  right: 99px;
  bottom: 32px;
  border-color: rgba(126, 199, 240, 0.37);
  background:
    radial-gradient(circle at 38% 28%, rgba(199, 236, 255, 0.17), transparent 34%),
    linear-gradient(145deg, rgba(26, 56, 83, 0.76), rgba(5, 15, 29, 0.92));
  color: #c5edff;
  box-shadow: 0 7px 20px rgba(0, 0, 0, 0.32), 0 0 20px rgba(94, 178, 230, 0.08);
}
.action-button.jump {
  width: 55px;
  height: 55px;
  right: 16px;
  bottom: 101px;
  color: #c9f5df;
  border-color: rgba(125, 202, 164, 0.3);
}
.action-button.jump svg { width: 32%; height: 32%; }
.action-button.jump .label { bottom: 8px; font-size: 5px; }
.action-button.potion {
  width: 45px;
  height: 45px;
  right: 94px;
  bottom: 108px;
  color: #f2c7c9;
  border-color: rgba(213, 112, 118, 0.3);
}
.action-button.potion svg { width: 38%; height: 38%; }
.action-button .count {
  position: absolute;
  right: 2px;
  top: 0;
  min-width: 17px;
  height: 17px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #d9a863;
  color: #24170a;
  font-size: 7px;
  font-weight: 800;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.3);
}

.tilt-indicator {
  position: absolute;
  left: 50%;
  bottom: calc(var(--safe-bottom) + 8px);
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 6px;
  color: rgba(165, 217, 228, 0.48);
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  transition: opacity 0.3s;
}
.tilt-indicator svg { width: 13px; height: 13px; }

.tutorial-card {
  position: absolute;
  left: 50%;
  top: calc(var(--safe-top) + 120px);
  width: 370px;
  transform: translateX(-50%);
  padding: 17px 19px 15px;
  border: 1px solid rgba(212, 238, 244, 0.14);
  background: linear-gradient(135deg, rgba(14, 31, 43, 0.76), rgba(4, 11, 20, 0.88));
  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.3);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  animation: card-in 0.6s 0.5s both cubic-bezier(0.2, 0.8, 0.2, 1);
  transition: opacity 0.4s, transform 0.4s;
  pointer-events: auto;
}
.tutorial-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 18px;
  right: 18px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(231, 189, 119, 0.45), transparent);
}
.tutorial-card.dismissed { opacity: 0; transform: translateX(-50%) translateY(-8px); pointer-events: none; }
@keyframes card-in { from { opacity: 0; transform: translateX(-50%) translateY(12px); } to { opacity: 1; transform: translateX(-50%); } }
.tutorial-close {
  position: absolute;
  top: 9px;
  right: 9px;
  width: 26px;
  height: 26px;
  display: grid;
  place-items: center;
  color: rgba(211, 232, 236, 0.45);
}
.tutorial-close svg { width: 13px; height: 13px; }
.tutorial-kicker { display: block; color: var(--gold); font-size: 7px; font-weight: 800; letter-spacing: 0.28em; text-transform: uppercase; }
.tutorial-card > strong { display: block; margin: 5px 0 5px; font-family: var(--serif); font-size: 18px; letter-spacing: 0.03em; }
.tutorial-card > p { margin: 0; color: rgba(199, 219, 224, 0.64); font-size: 10px; line-height: 1.6; }
.tutorial-card b { color: #e8dcc7; font-weight: 700; }
.tutorial-rows { display: flex; gap: 18px; margin-top: 12px; padding-top: 11px; border-top: 1px solid rgba(255, 255, 255, 0.07); }
.tutorial-rows span { display: flex; align-items: center; gap: 6px; color: rgba(195, 217, 222, 0.48); font-size: 7px; font-weight: 800; letter-spacing: 0.1em; text-transform: uppercase; }
.tutorial-rows i { width: 17px; height: 17px; display: grid; place-items: center; border: 1px solid rgba(216, 240, 245, 0.15); border-radius: 50%; }
.tutorial-rows .tut-stick { background: radial-gradient(circle, rgba(231, 189, 119, 0.7) 0 20%, transparent 23%); }
.tutorial-rows .tut-drag { border-radius: 3px; background: linear-gradient(90deg, transparent 40%, rgba(174, 223, 234, 0.6) 43% 57%, transparent 60%); }
.tutorial-rows .tut-paw svg { width: 10px; height: 10px; color: var(--gold); }

.look-cue {
  position: absolute;
  left: 55%;
  bottom: 28%;
  display: flex;
  align-items: center;
  gap: 9px;
  color: rgba(211, 234, 239, 0.45);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  animation: cue-float 3.5s infinite;
  transition: opacity 0.5s;
}
.look-cue span {
  width: 29px;
  height: 29px;
  border: 1px solid rgba(210, 238, 244, 0.25);
  border-radius: 50%;
  position: relative;
}
.look-cue span::before { content: "↔"; position: absolute; inset: 0; display: grid; place-items: center; font-size: 12px; color: var(--gold); }
.look-cue.hidden-cue { opacity: 0; }
@keyframes cue-float { 0%, 100% { transform: translateY(0); opacity: 0.5; } 50% { transform: translateY(-4px); opacity: 0.75; } }

/* ========================================================================== */
/* PAUSE                                                                      */
/* ========================================================================== */

.pause-panel {
  width: min(445px, 100%);
  padding: 34px 32px 27px;
  text-align: center;
}
.pause-emblem {
  width: 50px;
  height: 50px;
  margin: 0 auto 17px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(231, 189, 119, 0.34);
  transform: rotate(45deg);
  background: rgba(231, 189, 119, 0.06);
  box-shadow: 0 0 25px rgba(231, 189, 119, 0.08);
}
.pause-emblem svg { width: 23px; height: 23px; color: var(--gold); transform: rotate(-45deg); }
.pause-panel h2 { margin-top: 7px; }
.pause-sub { margin-bottom: 24px !important; font-size: 9px !important; letter-spacing: 0.11em; text-transform: uppercase; }
.pause-actions { display: flex; flex-direction: column; gap: 12px; }
.pause-actions > .primary-button { width: 100%; }
.settings-list { display: flex; flex-direction: column; border-top: 1px solid rgba(255, 255, 255, 0.08); border-bottom: 1px solid rgba(255, 255, 255, 0.08); margin: 3px 0; }
.setting-row {
  display: flex;
  align-items: center;
  gap: 11px;
  min-height: 59px;
  padding: 9px 3px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.055);
  text-align: left;
}
.setting-row:last-child { border-bottom: 0; }
.setting-icon { width: 34px; height: 34px; flex: none; display: grid; place-items: center; border: 1px solid rgba(210, 238, 244, 0.13); border-radius: 50%; color: var(--frost); }
.setting-icon svg { width: 16px; height: 16px; }
.setting-copy { flex: 1; display: flex; flex-direction: column; gap: 3px; }
.setting-copy strong { font-size: 10px; font-weight: 700; letter-spacing: 0.04em; }
.setting-copy small { color: rgba(194, 216, 221, 0.43); font-size: 8px; }
.toggle {
  width: 37px;
  height: 21px;
  border-radius: 99px;
  border: 1px solid rgba(211, 237, 243, 0.17);
  background: rgba(1, 5, 10, 0.42);
  position: relative;
  transition: all 0.2s;
  flex: none;
}
.toggle i { position: absolute; left: 3px; top: 3px; width: 13px; height: 13px; border-radius: 50%; background: rgba(188, 213, 219, 0.45); transition: transform 0.2s, background 0.2s, box-shadow 0.2s; }
.toggle.on { border-color: rgba(231, 189, 119, 0.45); background: rgba(108, 73, 29, 0.28); }
.toggle.on i { transform: translateX(16px); background: var(--gold-bright); box-shadow: 0 0 8px rgba(231, 189, 119, 0.5); }
.setting-icon .pause-sound-off { display: none; }
.setting-row.muted .pause-sound-on { display: none; }
.setting-row.muted .pause-sound-off { display: block; }
.text-button { color: rgba(201, 222, 226, 0.48); font-size: 8px; font-weight: 800; letter-spacing: 0.15em; text-transform: uppercase; padding: 9px; transition: color 0.2s; }
.text-button:hover { color: var(--gold); }
.pause-hint { margin-top: 15px !important; font-size: 8px !important; color: rgba(194, 216, 221, 0.35) !important; text-align: center; }

/* ========================================================================== */
/* DIALOGUE / MESSAGES / LOADING                                              */
/* ========================================================================== */

.dialogue-layer {
  position: absolute;
  inset: 0;
  z-index: 35;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  padding: 0 var(--safe-right) calc(var(--safe-bottom) + 18px) var(--safe-left);
  pointer-events: none;
  transition: opacity 0.3s, visibility 0.3s;
}
.dialogue-layer::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(0deg, rgba(2, 6, 12, 0.72), transparent 40%);
  pointer-events: none;
}
.dialogue-panel {
  position: relative;
  width: min(830px, 100%);
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 17px 19px;
  border: 1px solid rgba(214, 239, 245, 0.18);
  border-top-color: rgba(231, 189, 119, 0.4);
  background: linear-gradient(135deg, rgba(14, 29, 41, 0.94), rgba(5, 12, 21, 0.96) 62%);
  box-shadow: 0 24px 65px rgba(0, 0, 0, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(22px);
  -webkit-backdrop-filter: blur(22px);
  pointer-events: auto;
  animation: dialogue-in 0.4s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
@keyframes dialogue-in { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: none; } }
.dialogue-portrait { width: 85px; height: 85px; }
.dialogue-portrait svg { width: 80%; height: 80%; }
.dialogue-main { flex: 1; min-width: 0; padding: 7px 4px; }
.dialogue-name { display: block; color: var(--gold); font-family: var(--serif); font-size: 12px; font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; }
.dialogue-main p {
  margin: 8px 0 0;
  min-height: 42px;
  color: #dce9eb;
  font-family: var(--serif);
  font-size: clamp(14px, 1.5vw, 18px);
  line-height: 1.5;
  letter-spacing: 0.01em;
}
.dialogue-next {
  align-self: flex-end;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 8px 12px;
  color: rgba(231, 189, 119, 0.7);
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.17em;
  text-transform: uppercase;
  border: 1px solid rgba(231, 189, 119, 0.16);
  white-space: nowrap;
}
.dialogue-next svg { width: 10px; height: 10px; fill: currentColor; stroke: none; }
.dialogue-next:hover { color: var(--gold-bright); }

.fullscreen-message {
  position: absolute;
  inset: 0;
  z-index: 60;
  display: grid;
  place-items: center;
  padding: max(20px, env(safe-area-inset-top)) 20px max(20px, env(safe-area-inset-bottom));
  transition: opacity 0.6s, visibility 0.6s;
}
.message-scrim {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, rgba(34, 9, 14, 0.25), rgba(2, 5, 10, 0.92) 70%);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
}
.victory-scrim { background: radial-gradient(ellipse at center, rgba(14, 50, 54, 0.3), rgba(2, 7, 12, 0.93) 70%); }
.message-content {
  position: relative;
  z-index: 1;
  width: min(560px, 100%);
  text-align: center;
  animation: message-in 1s 0.2s both cubic-bezier(0.2, 0.8, 0.2, 1);
}
@keyframes message-in { from { opacity: 0; transform: translateY(16px); filter: blur(4px); } to { opacity: 1; transform: none; filter: none; } }
.message-sigil {
  width: 62px;
  height: 62px;
  display: grid;
  place-items: center;
  margin: 0 auto 23px;
  border: 1px solid rgba(210, 118, 128, 0.36);
  border-radius: 50%;
  color: #db8c97;
  background: rgba(76, 23, 30, 0.2);
  box-shadow: 0 0 35px rgba(139, 39, 53, 0.14);
}
.message-sigil svg { width: 28px; height: 28px; }
.message-content h2 {
  margin: 9px 0 12px;
  font-family: var(--serif);
  font-size: clamp(34px, 5vw, 56px);
  font-weight: 700;
  line-height: 1.02;
  letter-spacing: 0.01em;
  color: #e8f2f3;
}
.message-content > p { max-width: 400px; margin: 0 auto 27px; color: rgba(199, 218, 223, 0.65); font-size: 12px; line-height: 1.65; }
.victory-sigil { color: var(--gold-bright); border-color: rgba(231, 189, 119, 0.45); background: rgba(91, 68, 29, 0.18); box-shadow: 0 0 45px rgba(231, 189, 119, 0.13); }
.victory-content h2 { color: #f4e8cb; }
.victory-stats { display: flex; justify-content: center; gap: 38px; padding: 20px 0 24px; margin: 6px 0 22px; border-top: 1px solid rgba(255, 255, 255, 0.09); border-bottom: 1px solid rgba(255, 255, 255, 0.09); }
.victory-stats div { display: flex; flex-direction: column; gap: 5px; }
.victory-stats strong { font-family: var(--serif); font-size: 22px; font-weight: 600; color: var(--gold-bright); }
.victory-stats span { color: rgba(195, 218, 223, 0.43); font-size: 7px; font-weight: 800; letter-spacing: 0.2em; text-transform: uppercase; }
.victory-actions { display: flex; flex-direction: column; align-items: center; gap: 10px; }
.victory-actions .primary-button { min-width: 240px; }

.loading-screen {
  position: absolute;
  inset: 0;
  z-index: 90;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(ellipse at center, #0c1d2b, #03070d 68%);
  transition: opacity 0.8s ease, visibility 0.8s;
}
.loading-mark {
  position: relative;
  width: 58px;
  height: 58px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(231, 189, 119, 0.28);
  transform: rotate(45deg);
  margin-bottom: 28px;
}
.loading-mark svg { width: 25px; height: 25px; color: var(--gold); transform: rotate(-45deg); }
.loading-mark span {
  position: absolute;
  inset: -10px;
  border: 1px solid transparent;
  border-top-color: rgba(231, 189, 119, 0.45);
  border-radius: 50%;
  animation: loading-spin 1.8s linear infinite;
}
@keyframes loading-spin { to { transform: rotate(360deg); } }
.loading-kicker { color: var(--gold); font-family: var(--serif); font-size: 11px; font-weight: 700; letter-spacing: 0.5em; text-transform: uppercase; padding-left: 0.5em; }
.loading-screen p { margin: 11px 0 0; color: rgba(196, 218, 223, 0.45); font-size: 8px; font-weight: 700; letter-spacing: 0.2em; text-transform: uppercase; }

.rotate-hint {
  position: absolute;
  top: calc(var(--safe-top) + 78px);
  left: 50%;
  transform: translateX(-50%);
  z-index: 25;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border: 1px solid rgba(231, 189, 119, 0.3);
  border-radius: 99px;
  background: rgba(7, 15, 26, 0.75);
  color: var(--gold-bright);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  backdrop-filter: blur(10px);
  animation: toast-in 0.4s ease both;
  transition: opacity 0.4s;
}
.rotate-hint svg { width: 15px; height: 15px; }

/* ========================================================================== */
/* RESPONSIVE                                                                 */
/* ========================================================================== */

@media (max-width: 900px) {
  .title-hero { padding-left: clamp(0px, 3vw, 40px); }
  .game-logo { font-size: clamp(68px, 13vw, 126px); }
  .compass-wrap { width: min(340px, 42vw); }
  .action-cluster { transform: scale(0.94); transform-origin: right bottom; }
  .joystick-zone { transform: scale(0.94); transform-origin: left bottom; }
}

@media (max-width: 720px) {
  .title-screen { padding: var(--safe-top) 16px var(--safe-bottom); }
  .title-scrim {
    background:
      linear-gradient(180deg, rgba(2, 6, 12, 0.45), transparent 20%, transparent 46%, rgba(2, 6, 12, 0.9) 76%),
      linear-gradient(90deg, rgba(2, 6, 12, 0.45), transparent 80%);
  }
  .brand-copy small { display: none; }
  .brand-mark { width: 38px; height: 38px; }
  .brand-copy strong { font-size: 12px; letter-spacing: 0.22em; }
  .pill-button { width: 42px; padding: 0; justify-content: center; }
  .pill-button span, .pill-button .status-dot { display: none; }
  .desktop-only { display: none; }
  .title-hero {
    margin: auto 0;
    padding: 0 6px;
    max-width: 100%;
    transform: translateY(4vh);
  }
  .eyebrow { font-size: 8px; letter-spacing: 0.25em; gap: 9px; }
  .game-logo { font-size: clamp(63px, 19.5vw, 106px); }
  .game-subtitle { font-size: 10px; letter-spacing: 0.52em; margin-top: 11px; }
  .game-pitch { margin-top: 17px; font-size: 12px; line-height: 1.65; max-width: 335px; }
  .title-cta { margin-top: 22px; }
  .primary-button, .secondary-button { min-height: 48px; padding: 0 18px; font-size: 10px; }
  .secondary-button { padding: 0 20px; }
  .title-meta { margin-top: 18px; gap: 8px 14px; font-size: 7px; }
  .title-footer { font-size: 7px; gap: 10px; }
  .title-hint { text-align: right; }

