```
function cameraDistanceFactor(tx,tz,dx,dz,maxDist,camY) {
 if (camY > 6.2) return 1;
 let factor=1;
 for (const c of world.colliders) {
   if (c.low) continue;
   const ox=c.x-tx, oz=c.z-tz;
   const along=ox*dx+oz*dz;
   if (along <= 0.8 || along >= maxDist) continue;
   const perp=Math.abs(ox*dz-oz*dx);
   const clearance=c.radius+0.55;
   if (perp < clearance) {
      const f = Math.max(0.22, (along - 0.55)/maxDist);
      if (f < factor) factor=f;
   }
 }
 return factor;
}
